"""Closed Azure module and archive pins for the hosted commissioning fixture."""

from dataclasses import dataclass
from enum import Enum
from pathlib import Path


class DispatchMode(Enum):
    AZURE_1017 = "commission-azure-1017"
    AZURE_1020 = "commission-azure-1020"
    OBSERVE = "observe-candidate"
    BLOCKED = "blocked"


MODULE_PATHS = (
    ("wireguard", "kernel/drivers/net/wireguard/wireguard.ko.zst"),
    ("udp_tunnel", "kernel/net/ipv4/udp_tunnel.ko.zst"),
    ("ip6_udp_tunnel", "kernel/net/ipv6/ip6_udp_tunnel.ko.zst"),
    ("libcurve25519", "kernel/lib/crypto/libcurve25519.ko.zst"),
)


def module_paths(release):
    tree = Path(f"/lib/modules/{release}")
    return {name: tree / path for name, path in MODULE_PATHS}


@dataclass(frozen=True)
class ObservedClosure:
    order: tuple[str, ...]
    wireguard_depends: tuple[str, ...]
    signer: str
    vermagic: str


@dataclass(frozen=True)
class Profile:
    mode: DispatchMode
    release: str
    build: str
    version: str
    archive_bytes: int
    archive_sha256: str
    config_sha256: str
    builtin_sha256: str
    module_sha256: tuple[tuple[str, str], ...]
    observed_closure: ObservedClosure | None = None

    @property
    def image(self):
        return f"linux-image-{self.release}"

    @property
    def package(self):
        return f"linux-modules-{self.release}"

    @property
    def archive(self):
        return f"{self.package}_{self.version}_amd64.deb"

    @property
    def config(self):
        return Path(f"/boot/config-{self.release}")

    @property
    def builtin(self):
        return Path(f"/lib/modules/{self.release}/modules.builtin")

    def expected_members(self):
        paths = module_paths(self.release)
        return {self.config: self.config_sha256, self.builtin: self.builtin_sha256} | {
            paths[name]: digest for name, digest in self.module_sha256
        }

    def package_record(self, name):
        return {"package": name, "version": self.version, "architecture": "amd64"}


